import {destinationBackdrop} from '../shared/adventure-host.js';
import {DIPPER} from './pictures.js';
export function round(c,x,y,w,h,r,color){c.fillStyle=color;c.beginPath();c.roundRect(x,y,w,h,r);c.fill();}
function ball(c,x,y,r,color){c.fillStyle=color;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill();}
export function star(c,x,y,r=12,color='#ffe49b',t=0){c.save();c.translate(x,y+Math.sin(t*3+x)*3);c.fillStyle=color;c.beginPath();for(let i=0;i<10;i++){let a=i*Math.PI/5-Math.PI/2,s=i%2?r*.45:r;c.lineTo(Math.cos(a)*s,Math.sin(a)*s);}c.closePath();c.fill();c.restore();}
export function planet(c,x,y,r,t=0){ball(c,x,y,r,'#61bad9');c.save();c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.clip();for(let i=0;i<4;i++){const px=x+((i*47+t*10)%(r*2.6))-r*1.3;c.fillStyle='#88e1b1';c.beginPath();c.moveTo(px,y-r*.7);c.bezierCurveTo(px+r*.5,y-r*.95,px+r*.7,y-r*.15,px+r*.3,y);c.bezierCurveTo(px+r*.7,y+r*.4,px+r*.2,y+r*.9,px-r*.1,y+r*.6);c.bezierCurveTo(px-r*.3,y+r*.2,px-r*.5,y-r*.2,px,y-r*.7);c.fill();}c.fillStyle='#11285133';c.beginPath();c.ellipse(x+r*.55,y,r*.6,r,0,0,Math.PI*2);c.fill();c.restore();}
export function robot(c,x,y,t,happy=false){c.save();c.translate(x,y+Math.sin(t*3)*5);ball(c,0,-47,5,'#ffd88b');c.strokeStyle='#a6e8e5';c.lineWidth=4;c.beginPath();c.moveTo(0,-43);c.lineTo(0,-31);c.stroke();round(c,-24,-34,48,38,14,'#b9e7ed');round(c,-19,-29,38,23,10,'#243854');ball(c,-9,-18,4,'#b4f8e0');ball(c,9,-18,4,'#b4f8e0');round(c,-14,6,28,22,9,'#70b7d1');round(c,-27,happy?-15:8,9,19,4,'#f7d58c');round(c,18,happy?-15:8,9,19,4,'#f7d58c');ball(c,-6,34,6,'#435779');ball(c,8,34,6,'#435779');c.restore();}
export function explorer(c,p,t,win=false){c.save();c.translate(p.x+16,p.y+58);c.scale(p.face||1,p.land>0?.9:1);if(p.hurt>0&&Math.floor(t*12)%2)c.globalAlpha=.5;const stride=p.grounded?Math.sin(t*15)*Math.min(1,Math.abs(p.vx)/280):.6;round(c,-19,-40,12,29,5,'#8ca3d2');round(c,-13,-40,28,30,10,'#f1f5ec');round(c,-10,-30,22,12,4,'#6cd5d1');round(c,-11,-12+stride*4,10,14,4,'#8da4ed');round(c,5,-12-stride*4,10,14,4,'#8da4ed');round(c,-23,win?-55:-35,10,23,5,'#ffd996');round(c,14,win?-55:-35,10,23,5,'#ffd996');ball(c,1,-58,25,'#e8efed');ball(c,3,-58,19,'#264765');ball(c,5,-54,14,'#efb98b');round(c,-9,-73,27,8,4,'#4d3948');ball(c,1,-56,2,'#333a53');ball(c,12,-56,2,'#333a53');c.strokeStyle='#a65f59';c.lineWidth=2;c.beginPath();c.arc(7,-52,5,0,Math.PI);c.stroke();round(c,12,-77,10,6,2,'#79dad6');c.restore();}
export function titleArt(c,t){const g=c.createLinearGradient(0,0,1200,720);g.addColorStop(0,'#123d57');g.addColorStop(.5,'#26335e');g.addColorStop(1,'#5f4b89');c.fillStyle=g;c.fillRect(0,0,1200,720);for(let i=0;i<100;i++)star(c,(i*193)%1200,(i*97)%720,i%7===0?5:2,'#cadbfa',t);ball(c,920,366,209,'#8882c929');ball(c,920,366,169,'#a299e52a');planet(c,920,366,128,t);star(c,1000,113,38,'#ffd987',t);c.strokeStyle='#e4c9fc55';c.lineWidth=2;c.setLineDash([6,9]);c.beginPath();c.ellipse(920,366,245,160,-.3,0,Math.PI*2);c.stroke();c.setLineDash([]);ball(c,740,481,31,'#eee7d4');ball(c,732,473,8,'#c6c4c6');ball(c,750,490,10,'#c6c4c6');round(c,690,624,390,140,60,'#647aaf');round(c,692,624,386,16,8,'#b4c4e3');explorer(c,{x:810,y:566,face:1,grounded:true,vx:0},t,true);robot(c,975,559,t,true);c.fillStyle='#badedc';c.font='700 17px Trebuchet MS';c.textAlign='center';c.fillText('LUMINARA • JUNIOR SPACE EXPLORERS',900,696);}
export function drawWorld(c,w,p,cam,t,effects,run){const night=w.index>0||w.night;const g=c.createLinearGradient(0,0,0,720);g.addColorStop(0,w.index===1?'#10203e':night?'#202444':'#57a8c4');g.addColorStop(1,w.index===1?'#4d558c':night?'#514475':'#b5e3c9');c.fillStyle=g;c.fillRect(0,0,1200,720);for(let i=0;i<65;i++){let x=((i*191-cam*.15)%1300+1300)%1300;if(night)star(c,x,25+(i*67)%450,i%9?2:5,'#dbe5fc',t);else if(i<8){const y=145+(i%3)*85;ball(c,x,y,15,'#ffffff55');ball(c,x+22,y-9,22,'#ffffff55');ball(c,x+43,y,16,'#ffffff55');}}if(w.index===0){ball(c,1000,135,52,night?'#eee8d7':'#ffdb85');}else if(w.index===1)planet(c,980-cam*.01,160,77,t*.2);else{const pp=DIPPER;c.save();c.translate(650-cam*.03,50);c.scale(.9,.9);c.strokeStyle='#9eaadf70';c.lineWidth=2;c.beginPath();['alkaid','mizar','alioth','megrez','phecda','merak','dubhe','megrez'].forEach((n,i)=>i?c.lineTo(...pp[n]):c.moveTo(...pp[n]));c.stroke();for(const n of Object.keys(pp))if(n!=='polaris')star(c,...pp[n],5,'#d7ddf8',t);star(c,...pp.polaris,run?.observatory?8+run.observatory*5:6,run?.observatory?'#ffe18e':'#8c8bad',t);c.restore();}
 destinationBackdrop(c,w.index,cam,t);c.save();c.translate(-Math.round(cam),0);const cols=w.index===0?['#85d3b5','#315b72']:w.index===1?['#c3c5dc','#65698f']:['#bab4ef','#514b87'];
 for(const s of w.platforms){if(s.x+s.w<cam||s.x>cam+1250)continue;round(c,s.x,s.y,s.w,s.h,10,cols[1]);round(c,s.x,s.y,s.w,14,7,cols[0]);if(s.ground){for(let x=s.x+40;x<s.x+s.w;x+=110){ball(c,x,s.y+48,10,cols[0]+'77');ball(c,x+30,s.y+103,5,cols[0]+'77');}}if(s.moving&&w.index===0)planet(c,s.x+75,s.y+48,33,t*2);else if(s.moving){star(c,s.x+75,s.y+39,13,'#88e4db',t);}}
 for(const v of w.crystals)if(!v.taken&&v.x>cam-30&&v.x<cam+1230){if(w.index===1&&v.id%4===0){ball(c,v.x,v.y,12,'#d2d7e8');ball(c,v.x-4,v.y-3,4,'#929cc3');}else star(c,v.x,v.y,v.bonus?16:12,v.bonus?'#a5f0e5':'#ffe28c',t);}
 for(const s of w.stations){if(s.x<cam-180||s.x>cam+1350)continue;if(s.type==='final'){round(c,s.x-90,388,180,146,45,'#798bb4');round(c,s.x-70,401,140,70,24,'#273c5c');for(let i=0;i<3;i++)star(c,s.x-42+i*42,435,14,i<(run?.observatory||0)?'#ffe597':'#647794',t);robot(c,s.x,352,t,!!s.done);}else if(s.name.includes('chest')){round(c,s.x-36,490,72,45,9,'#8c8bc3');round(c,s.x-38,479,76,23,7,'#c8c2ee');star(c,s.x,502,10,'#ffdd85',t);}else{round(c,s.x-25,478,50,57,10,'#b3bde0');round(c,s.x-19,484,38,28,7,s.done?'#75dac0':'#354c75');star(c,s.x,464,16,s.done?'#a6f2dc':'#ffde8c',t);}c.textAlign='center';c.font='900 17px Trebuchet MS';c.fillStyle='#fff4ce';c.fillText(s.name,s.x,405);if(!s.done){const gate=s.x+150;round(c,gate,334,36,201,10,'#87c2e1aa');for(let i=0;i<4;i++)star(c,gate+18,356+i*47,8,'#fff2be',t);}else{c.fillStyle='#c2f9d8';c.font='900 24px Trebuchet MS';c.fillText('✓',s.x,450);}}
 for(const x of [100,2250,3950,5650]){c.strokeStyle='#e1f2df';c.lineWidth=4;c.beginPath();c.moveTo(x,535);c.lineTo(x,457);c.stroke();round(c,x,457,34,22,5,x<=p.checkpoint?'#8be4c4':'#8d9fc9');star(c,x+17,467,7,'#fff4cf',t);}
 round(c,5910,382,125,153,55,'#b9c4df');round(c,5924,395,97,140,45,'#4b7691');star(c,5972,453,31,'#ffdf9a',t);explorer(c,p,t,run?.won);robot(c,p.x-50,p.y+4,t,run?.won);for(const e of effects){c.globalAlpha=Math.max(0,e.life);star(c,e.x,e.y,5,e.color,t);}c.globalAlpha=1;c.restore();}
